module.exports = "// One specimen layer per cell: (compartment, network, membrane, stain).\n// look[i].x is visibility, look[i].y how far cell i has been digested (0..1),\n// look[i].z how strongly the network of a large cell takes the stain.\nstruct Scene { large:u32,cells:u32,pad0:u32,pad1:u32,look:array<vec4f,16> }\n@group(0) @binding(0) var layers:texture_2d_array<f32>;\n@group(0) @binding(1) var outputImage:texture_storage_2d<rgba16float,write>;\n@group(0) @binding(2) var<uniform> scene:Scene;\n@compute @workgroup_size(16,16)\nfn composite(@builtin(global_invocation_id) id:vec3u){\n  let p=vec2i(id.xy);if(any(p>=vec2i(textureDimensions(outputImage)))){return;}\n  var sum=vec4f(0);\n  for(var i=0u;i<scene.cells;i++){\n    let look=scene.look[i];if(look.x<=0.0){continue;}\n    let layer=textureLoad(layers,p,i32(i),0);\n    sum.r+=layer.r;sum.b+=layer.b;\n    // A large cell's g is its network density, positive, or its nucleus stain, negative: only the stain is kept.\n    if(i<scene.large){sum.a+=layer.a*look.z;sum.g+=min(layer.g,0.0);}\n    // Prey take a second stain (g). As a prey is digested, the stain of its\n    // network gives way to an even fill of its shrinking compartment.\n    else{sum.g+=mix(layer.a,0.6*layer.r,look.y);}\n  }\n  sum.r=min(1.0,sum.r);textureStore(outputImage,p,sum);\n}\n";

